-- This module has not completed a migration yet. A previous failed Railway run may have
-- left a partial account_coa table because MySQL auto-commits DDL. Reset that partial table.
DROP TABLE IF EXISTS account_coa;

CREATE TABLE account_coa (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  HeadCode BIGINT UNSIGNED NOT NULL, HeadName VARCHAR(100) NOT NULL, PHeadName VARCHAR(100) NULL,
  parent_id BIGINT UNSIGNED NULL, HeadLevel INT NOT NULL DEFAULT 0, IsActive BOOLEAN NOT NULL DEFAULT TRUE,
  IsTransaction BOOLEAN NOT NULL DEFAULT FALSE, IsGL BOOLEAN NOT NULL DEFAULT FALSE, IsJournal BOOLEAN NOT NULL DEFAULT FALSE,
  HeadType CHAR(1) NULL, IsBudget BOOLEAN NOT NULL DEFAULT FALSE, IsDepreciation BOOLEAN NOT NULL DEFAULT FALSE,
  customer_id BIGINT UNSIGNED NULL, aggre_id BIGINT UNSIGNED NULL, supplier_id BIGINT UNSIGNED NULL, employee_id BIGINT UNSIGNED NULL,
  payment_method_id VARCHAR(255) NULL, bank_id VARCHAR(255) NULL, node_type ENUM('root','group','control','ledger') NOT NULL DEFAULT 'group',
  allows_manual_children BOOLEAN NOT NULL DEFAULT FALSE, is_system BOOLEAN NOT NULL DEFAULT FALSE,
  CreateBy VARCHAR(50) NULL, CreateDate DATE NULL, UpdateBy VARCHAR(50) NULL, UpdateDate DATE NULL, deleted_at TIMESTAMP NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY account_coa_head_code_unique (HeadCode), UNIQUE KEY account_coa_customer_unique (customer_id),
  UNIQUE KEY account_coa_supplier_unique (supplier_id), UNIQUE KEY account_coa_employee_unique (employee_id), KEY account_coa_parent_index (parent_id),
  CONSTRAINT account_coa_parent_fk FOREIGN KEY (parent_id) REFERENCES account_coa(id) ON DELETE RESTRICT,
  CONSTRAINT account_coa_customer_fk FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  CONSTRAINT account_coa_supplier_fk FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
  CONSTRAINT account_coa_employee_fk FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

