-- Resolve the hierarchy after every seed row exists. PHeadName is retained for compatibility with the supplied schema.
UPDATE account_coa child
JOIN account_coa parent ON parent.HeadName = child.PHeadName
SET child.parent_id = parent.id
WHERE child.PHeadName IS NOT NULL;
